// CISO KPI Dashboard - Protection Value
let BlockedThreats = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where DeliveryAction in ("Blocked", "Quarantined") | where isnotempty(ThreatTypes) | count);
let DeliveredThreats = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where DeliveryAction == "Delivered" | where isnotempty(ThreatTypes) | count);
let ZAPRemediated = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger == "ZAP" | where ActionResult == "Success" | count);
let ClicksBlocked = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | where IsClickedThrough == false | count);
let ThreatBlockRate = round(toreal(BlockedThreats) / (BlockedThreats + DeliveredThreats + 1) * 100, 1);
let TotalPrevented = BlockedThreats + ZAPRemediated + ClicksBlocked;
let EstimatedCostSaved = (BlockedThreats + ZAPRemediated) * 250;
print Metric = dynamic(["🛡️ Threats Blocked", "⚡ ZAP Remediated", "👆 Clicks Blocked", "🎯 Block Rate %", "✅ Total Prevented", "💰 Est. Cost Saved"]),
      Value = pack_array(BlockedThreats, ZAPRemediated, ClicksBlocked, ThreatBlockRate, TotalPrevented, EstimatedCostSaved)
| mv-expand Metric to typeof(string), Value to typeof(long)

// URLs Blocked at Time of Click
UrlClickEvents
| where TimeGenerated {TimeRange}
| where IsClickedThrough == false
| summarize Count = count()
| project Metric = "👆 At Click", Value = Count

// Total URL Protection
let URLsAtDelivery = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where DeliveryAction in ("Blocked", "Quarantined") | where DetectionMethods has_any ("URL detonation", "URL reputation", "Safe Links", "URL") | count);
let URLsViaAutomation = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger has_any ("Automation", "Playbook", "AIR", "ZAP") | where ActionResult == "Success" | count);
let URLsAtClick = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | where IsClickedThrough == false | count);
let Total = URLsAtDelivery + URLsViaAutomation + URLsAtClick;
print Metric = "🛡️ Total Stopped", Value = Total

// Total File Protection (V2 - OfficeActivity removed)
// Malicious files at delivery (email attachments) + malicious files detected in SharePoint/OneDrive/Teams
let FilesAtDelivery = toscalar(
    EmailEvents
    | where TimeGenerated {TimeRange}
    | where EmailDirection == "Inbound"
    | where DeliveryAction in ("Blocked", "Quarantined")
    | where ThreatTypes has "Malware" or DetectionMethods has_any ("File detonation", "Safe Attachments")
    | where AttachmentCount > 0
    | count
);
let FilesInCloud = toscalar(
    union isfuzzy=true
        (FileMaliciousContentInfo
        | where TimeGenerated {TimeRange}
        | where isnotempty(SHA256) or isnotempty(FileName)
        | count)
);
let Total = FilesAtDelivery + coalesce(FilesInCloud, 0);
print Metric = "🛡️ Total Protected", Value = Total

// Unique URLs with threats blocked
UrlClickEvents
| where TimeGenerated {TimeRange}
| where IsClickedThrough == false or isnotempty(ThreatTypes)
| summarize UniqueURLs = dcount(Url)
| project Value = UniqueURLs, Description = "unique URLs with threats blocked by Safe Links (detonation, reputation)"

// Clicks blocked at time-of-click
UrlClickEvents
| where TimeGenerated {TimeRange}
| where IsClickedThrough == false
| summarize ClicksBlocked = count()
| project Value = ClicksBlocked, Description = "clicks on unwanted sites blocked at time-of-click"

// Users Protected from clicking malicious links
UrlClickEvents
| where TimeGenerated {TimeRange}
| where IsClickedThrough == false
| summarize UsersProtected = dcount(AccountUpn)
| project Value = UsersProtected, Description = "users protected from clicking malicious links"

// Phish Delivery Location Analysis with Observations
let PhishToInbox = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryLocation == "Inbox/folder" or (DeliveryAction == "Delivered" and DeliveryLocation !has "Junk") | count);
let PhishToJunk = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryLocation has "Junk" | count);
let PhishToQuarantine = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryAction == "Quarantined" or DeliveryLocation has "Quarantine" | count);
let PhishCustom = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryAction !in ("Delivered", "Blocked", "Quarantined") | count);
let PhishBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryAction == "Blocked" | count);
print Location = dynamic(["📥 Inbox", "📁 Junk Folder", "🔒 Quarantine", "🚫 Blocked", "⚙️ Custom Action"]),
      Count = pack_array(PhishToInbox, PhishToJunk, PhishToQuarantine, PhishBlocked, PhishCustom),
      Risk = dynamic(["🔴 High Risk", "🟠 Medium Risk", "✅ Safe", "✅ Safe", "🟡 Review"])
| mv-expand Location to typeof(string), Count to typeof(long), Risk to typeof(string)
| where Count > 0

// Delivery Location Observations
let PhishToInbox = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryLocation == "Inbox/folder" or (DeliveryAction == "Delivered" and DeliveryLocation !has "Junk") | count);
let PhishToJunk = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryLocation has "Junk" | count);
let PhishCustom = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | where DeliveryAction !in ("Delivered", "Blocked", "Quarantined") | count);
print Observation = pack_array(
    iff(PhishToInbox > 0, strcat("⚠️ **Phish to Inbox:** You have configuration allowing phish to be delivered to inbox. There are **", PhishToInbox, "** messages classified as phish sent to inbox", iff(PhishCustom > 0, strcat(", and **", PhishCustom, "** with custom action"), ""), ". Considering these are potentially malicious, it's advisable to send to quarantine."), ""),
    iff(PhishToJunk > 0, strcat("🟡 **Phish to Junk:** There are **", PhishToJunk, "** messages classified as phish sent to junk folder, which users may mistake as safe. Be aware third-party vendors often purge items from this folder."), ""),
    iff(PhishToInbox == 0 and PhishToJunk == 0, "✅ **All phish properly quarantined or blocked.** No action required.", ""))
| mv-expand Observation to typeof(string)
| where isnotempty(Observation)

// Automation Overview - AIR Statistics
let TotalAlerts = toscalar(SecurityAlert | where TimeGenerated {TimeRange} | where ProductName has_any ("Office 365", "Microsoft Defender for Office 365", "MDO") | count);
let AutomationRan = toscalar(SecurityAlert | where TimeGenerated {TimeRange} | where ProductName has_any ("Office 365", "Microsoft Defender for Office 365") | where Status has_any ("InProgress", "Resolved", "Dismissed") | count);
let UniqueIncidents = toscalar(SecurityIncident | where TimeGenerated {TimeRange} | where Labels has_any ("Office365", "MDO", "Email", "Phishing", "Malware", "BEC") or Title has_any ("email", "phish", "malware", "spam") | count);
let AutoClosed = toscalar(SecurityIncident | where TimeGenerated {TimeRange} | where Status == "Closed" | count);
let CorrelationRate = iff(TotalAlerts > 0 and UniqueIncidents > 0, toint(round(toreal(TotalAlerts - UniqueIncidents) / TotalAlerts * 100, 0)), 0);
print Metric = dynamic(["🔔 MDO Alerts Processed", "📊 Correlated to Incidents", "🤖 Auto-Closed Incidents", "📈 Correlation Rate %"]),
      Value = pack_array(TotalAlerts, UniqueIncidents, AutoClosed, CorrelationRate),
      Description = dynamic(["by automation playbooks", "reducing alert fatigue", "without manual intervention", "alerts grouped into incidents"])
| mv-expand Metric to typeof(string), Value to typeof(long), Description to typeof(string)

// Automation Actions Analysis
let ZAPActions = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger == "ZAP" | count);
let AIRActions = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger has_any ("AIR", "Automation", "Playbook", "AutoRemediation") | count);
let AdminActions = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger has_any ("Admin", "Manual") | count);
let PendingApproval = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionResult has_any ("Pending", "PendingApproval") | count);
let TimedOut = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionResult has_any ("TimedOut", "Expired", "Failed") | count);
print ActionType = dynamic(["⚡ ZAP Remediation", "🤖 AIR Automation", "👨‍💼 Admin Manual", "⏳ Pending Approval", "⏱️ Timed Out"]),
      Count = pack_array(ZAPActions, AIRActions, AdminActions, PendingApproval, TimedOut),
      Status = dynamic(["Automatic", "Automatic", "Manual", "Requires Action", "Requires Review"])
| mv-expand ActionType to typeof(string), Count to typeof(long), Status to typeof(string)

// Automation Observations
let TotalAlerts = toscalar(SecurityAlert | where TimeGenerated {TimeRange} | where ProductName has_any ("Office 365", "Microsoft Defender for Office 365") | count);
let UniqueIncidents = toscalar(SecurityIncident | where TimeGenerated {TimeRange} | where Labels has_any ("Office365", "MDO", "Email") or Title has_any ("email", "phish") | count);
let AutoClosed = toscalar(SecurityIncident | where TimeGenerated {TimeRange} | where Status == "Closed" | count);
let TotalIncidents = toscalar(SecurityIncident | where TimeGenerated {TimeRange} | count);
let PendingApproval = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionResult has "Pending" | count);
let TimedOut = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionResult has_any ("TimedOut", "Expired") | count);
let CorrelationPct = iff(TotalAlerts > 0 and UniqueIncidents > 0, toint(round(toreal(TotalAlerts - UniqueIncidents) / TotalAlerts * 100, 0)), toint(0));
let AutoCloseRate = iff(TotalIncidents > 0, toint(round(toreal(AutoClosed) / TotalIncidents * 100, 0)), toint(0));
let ManualRequired = TotalIncidents - AutoClosed;
print Observation = pack_array(
    iff(TotalAlerts > 0, strcat("⚡ **Automation playbooks ran on ", TotalAlerts, " MDO alerts.** These playbooks run automatically when certain alerts fire, consisting of automated activities like re-detonating URLs/files, hunting, and remediation."), ""),
    iff(UniqueIncidents > 0 and TotalAlerts > UniqueIncidents, strcat("📊 **Automation correlated ", TotalAlerts, " alerts into ", UniqueIncidents, " unique incidents** (correlation: ", CorrelationPct, "%). Incidents are grouped by likeness, reducing total workload."), ""),
    iff(AutoClosed > 0, strcat("✅ **", AutoClosed, " incidents were automatically closed** (", AutoCloseRate, "% of incidents closed by automation without staff intervention). After automation, ", ManualRequired, " required manual investigation."), ""),
    iff(PendingApproval > 0, strcat("⏳ **Automation has actions pending approval in ", PendingApproval, " items.** When automation runs, certain actions may require your approval. You can [turn on auto-approval](https://security.microsoft.com/action-center) for certain action types."), ""),
    iff(TimedOut > 0, strcat("⚠️ **Automation found ", TimedOut, " threats where remediation timed out awaiting approval.** If actions are not approved within 7 days, they will time out. Consider enabling auto-approval for certain action types."), ""))
| mv-expand Observation to typeof(string)
| where isnotempty(Observation)

// Actions Taken Summary
let ZAP = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger == "ZAP" | count);
let Admin = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger has_any ("Admin", "Manual", "Submission") | count);
let PolicyBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where DeliveryAction == "Blocked" | count);
let Quarantined = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where DeliveryAction == "Quarantined" | count);
let SafeLinks = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | where IsClickedThrough == false | count);
print Action = dynamic(["ZAP Auto-Purge", "Admin Remediation", "Policy Blocked", "Quarantined", "Safe Links Blocked"]),
      Count = pack_array(ZAP, Admin, PolicyBlocked, Quarantined, SafeLinks),
      Category = dynamic(["Automated", "Manual", "Prevention", "Prevention", "Prevention"])
| mv-expand Action to typeof(string), Count to typeof(long), Category to typeof(string)

// Weekly Trend - Threats vs Actions
let Threats = EmailEvents
| where TimeGenerated {TimeRange}
| where isnotempty(ThreatTypes)
| summarize ThreatsDetected = count() by bin(TimeGenerated, 1d);
let Actions = EmailPostDeliveryEvents
| where TimeGenerated {TimeRange}
| summarize ActionsTaken = count() by bin(TimeGenerated, 1d);
Threats
| join kind=leftouter Actions on TimeGenerated
| project TimeGenerated, ThreatsDetected, ActionsTaken = coalesce(ActionsTaken, 0)

// Email Security Risk Score
let PhishCount = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Phish" | count);
let MalCount = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Malware" | count);
let SpamCnt = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where ThreatTypes has "Spam" | count);
let BECCount = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailActionPolicy has_any ("Anti-phishing", "impersonation", "domain") | count);
let RiskScore = min_of(100, (PhishCount / 10) + (MalCount * 5) + (BECCount * 10) + (SpamCnt / 100));
let RiskLevel = case(RiskScore >= 80, "🔴 CRITICAL", RiskScore >= 60, "🟠 HIGH", RiskScore >= 40, "🟡 MEDIUM", "🟢 LOW");
print Metric = dynamic(["🎯 Risk Score", "📊 Risk Level", "🎣 Phishing", "🦠 Malware", "📧 Spam", "💼 BEC Indicators"]),
      Value = pack_array(RiskScore, 0, PhishCount, MalCount, SpamCnt, BECCount),
      DisplayValue = pack_array(tostring(toint(RiskScore)), RiskLevel, tostring(PhishCount), tostring(MalCount), tostring(SpamCnt), tostring(BECCount))
| mv-expand Metric to typeof(string), Value to typeof(long), DisplayValue to typeof(string)

// Post-Delivery Protection Summary (V2 - OfficeActivity removed)
let ZAPRemoved = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger == "ZAP" | where ActionResult == "Success" | count);
let AdminRemediated = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger has_any ("Admin", "Manual", "Submission") | where ActionResult == "Success" | count);
let SafeLinksBlocked = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | where IsClickedThrough == false | count);
let SafeLinksAllowed = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | where IsClickedThrough == true | count);
let CollabMalware = toscalar(
    union isfuzzy=true
        (FileMaliciousContentInfo
        | where TimeGenerated {TimeRange}
        | count)
);
print Category = dynamic(["📧 Email - ZAP Purged", "👤 Email - Admin Remediated", "🔗 Safe Links - Blocked", "✅ Safe Links - Allowed", "📁 Collab Files - Malicious"]),
      Count = pack_array(ZAPRemoved, AdminRemediated, SafeLinksBlocked, SafeLinksAllowed, coalesce(CollabMalware, 0))
| mv-expand Category to typeof(string), Count to typeof(long)

// Trusted vs Untrusted Location Summary
SigninLogs
| where TimeGenerated {TimeRange}
| extend IsTrusted = iff(NetworkLocationDetails has "trustedNamedLocation", "🟢 Trusted Location", "🔴 Untrusted Location")
| summarize SignInCount = count(), UniqueUsers = dcount(UserPrincipalName), RiskySignIns = countif(RiskLevelDuringSignIn in ("medium", "high")) by IsTrusted
| order by IsTrusted asc

// URL Click Timeline by Threat Type
UrlClickEvents
| where TimeGenerated {TimeRange}
| where isnotempty(ThreatTypes)
| summarize Count = count() by ThreatTypes, bin(TimeGenerated, 1h)
| order by TimeGenerated asc

// Post-Delivery Events Timeline (includes ZAP, Admin, User actions)
EmailPostDeliveryEvents
| where TimeGenerated {TimeRange}
| summarize Count = count() by ActionTrigger, bin(TimeGenerated, 1h)
| order by TimeGenerated asc

// Priority Accounts Protected - Summary
let PriorityPatterns = dynamic(["CEO", "CFO", "CTO", "CISO", "COO", "President", "Director", "VP", "Vice President", "Executive", "Chief", "Partner", "Managing", "Principal"]);
let PriorityRecipients = EmailEvents
| where TimeGenerated {TimeRange}
| where EmailDirection == "Inbound"
| where isnotempty(ThreatTypes) or DeliveryAction in ("Blocked", "Quarantined")
| where RecipientEmailAddress has_any (PriorityPatterns) or Subject has_any (PriorityPatterns)
| distinct RecipientEmailAddress;
let ProtectedCount = toscalar(PriorityRecipients | count);
let TotalThreatsBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where RecipientEmailAddress in (PriorityRecipients) | where DeliveryAction in ("Blocked", "Quarantined") | count);
let PhishBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where RecipientEmailAddress in (PriorityRecipients) | where ThreatTypes has "Phish" and DeliveryAction in ("Blocked", "Quarantined") | count);
let MalwareBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where RecipientEmailAddress in (PriorityRecipients) | where ThreatTypes has "Malware" and DeliveryAction in ("Blocked", "Quarantined") | count);
print Metric = dynamic(["⭐ Priority Accounts Protected", "🛡️ Total Threats Blocked", "🎣 Phish Blocked", "🦠 Malware Blocked"]),
      Value = pack_array(ProtectedCount, TotalThreatsBlocked, PhishBlocked, MalwareBlocked),
      Description = dynamic(["from threats", "for priority accounts", "for priority accounts", "for priority accounts"])
| mv-expand Metric to typeof(string), Value to typeof(long), Description to typeof(string)

// Spoofing Detection Summary
let TotalInbound = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | count);
let SpoofDetected = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where DetectionMethods has_any ("Spoof", "DMARC", "SPF fail", "DKIM fail") | count);
let SpoofBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where DetectionMethods has_any ("Spoof", "DMARC", "SPF fail") | where DeliveryAction in ("Blocked", "Quarantined") | count);
let SpoofDelivered = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where DetectionMethods has_any ("Spoof", "DMARC") | where DeliveryAction == "Delivered" | count);
let ImpersonationDetected = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where DetectionMethods has_any ("Impersonation", "User impersonation", "Domain impersonation") | count);
print Metric = dynamic(["🎭 Spoof Attempts Detected", "🛡️ Spoofs Blocked", "⚠️ Spoofs Delivered", "👤 Impersonation Detected"]),
      Value = pack_array(SpoofDetected, SpoofBlocked, SpoofDelivered, ImpersonationDetected)
| mv-expand Metric to typeof(string), Value to typeof(long)

// Alert Overview Metrics
let HighSev = toscalar(AlertInfo | where TimeGenerated {TimeRange} | where ServiceSource has_any ("Office 365", "Microsoft Defender for Office 365", "MDO", "Microsoft 365 Defender") | where Severity == "High" | count);
let MedSev = toscalar(AlertInfo | where TimeGenerated {TimeRange} | where ServiceSource has_any ("Office 365", "Microsoft Defender for Office 365", "MDO", "Microsoft 365 Defender") | where Severity == "Medium" | count);
let MDOTotal = toscalar(AlertInfo | where TimeGenerated {TimeRange} | where ServiceSource has_any ("Office 365", "Microsoft Defender for Office 365", "MDO", "Microsoft 365 Defender") | count);
let IdentityTotal = toscalar(AlertInfo | where TimeGenerated {TimeRange} | where ServiceSource has_any ("Azure AD", "Microsoft Entra", "MCAS", "Identity Protection") | count);
let AiTMCount = toscalar(AlertInfo | where TimeGenerated {TimeRange} | where Title has_any ("AiTM", "adversary-in-the-middle", "token theft", "session hijack") | count);
print Metric = dynamic(["🔴 High Severity", "🟡 Medium Severity", "📧 Email Alerts", "🔐 Identity Alerts", "⚡ AiTM Alerts"]),
      Value = pack_array(HighSev, MedSev, MDOTotal, IdentityTotal, AiTMCount)
| mv-expand Metric to typeof(string), Value to typeof(long)

// Alert Categories Distribution
AlertInfo
| where TimeGenerated {TimeRange}
| where ServiceSource has_any ("Office 365", "Microsoft Defender for Office 365", "MDO", "Azure AD", "Microsoft Entra", "MCAS", "Microsoft 365 Defender")
| summarize Count = count() by Category
| order by Count desc

// Alert Timeline by Severity
AlertInfo
| where TimeGenerated {TimeRange}
| where ServiceSource has_any ("Office 365", "MDO", "Azure AD", "Microsoft Entra", "Microsoft 365 Defender")
| summarize Count = count() by Severity, bin(TimeGenerated, 4h)
| order by TimeGenerated asc

// Attack Timeline - Email to Identity Compromise
let TimelineBin = 4h;
AlertInfo
| where TimeGenerated {TimeRange}
| where ServiceSource has_any ("Office 365", "MDO", "Azure AD", "Microsoft Entra", "MCAS", "Microsoft 365 Defender")
| where Category has_any ("InitialAccess", "CredentialAccess", "Persistence", "Phishing", "Collection")
| summarize Count = count() by Category, bin(TimeGenerated, TimelineBin)
| order by TimeGenerated asc

// High-Risk Users with Email + Identity Alerts
let EmailAffectedUsers = AlertEvidence
| where TimeGenerated {TimeRange}
| join kind=inner (
    AlertInfo
    | where TimeGenerated {TimeRange}
    | where ServiceSource has_any ("Office 365", "MDO", "Microsoft 365 Defender")
) on AlertId
| where isnotempty(AccountUpn)
| summarize EmailAlertCount = dcount(AlertId), EmailAlertTitles = make_set(Title, 5) by AccountUpn;
let IdentityAffectedUsers = AlertEvidence
| where TimeGenerated {TimeRange}
| join kind=inner (
    AlertInfo
    | where TimeGenerated {TimeRange}
    | where ServiceSource has_any ("Azure AD", "Microsoft Entra", "MCAS", "Identity Protection")
) on AlertId
| where isnotempty(AccountUpn)
| summarize IdentityAlertCount = dcount(AlertId), IdentityAlertTitles = make_set(Title, 5) by AccountUpn;
EmailAffectedUsers
| join kind=inner IdentityAffectedUsers on AccountUpn
| extend TotalAlerts = EmailAlertCount + IdentityAlertCount
| extend RiskLevel = case(
    TotalAlerts > 10, "🔴 Critical",
    TotalAlerts > 5, "🟠 High",
    TotalAlerts > 2, "🟡 Medium",
    "🟢 Low")
| order by TotalAlerts desc
| project RiskLevel, AccountUpn, EmailAlertCount, EmailAlertTitles, IdentityAlertCount, IdentityAlertTitles, TotalAlerts

// Preset Security Policies - Coverage Analysis
let TotalInbound = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | count);
let StandardProtected = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where isnotempty(EmailActionPolicy) | where EmailActionPolicy has_any ("Default", "Standard") | count);
let StrictProtected = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where isnotempty(EmailActionPolicy) | where EmailActionPolicy has "Strict" | count);
let CustomPolicy = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where isnotempty(EmailActionPolicy) | where not(EmailActionPolicy has_any ("Default", "Standard", "Strict")) | count);
let NoPolicy = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | where isempty(EmailActionPolicy) or EmailActionPolicy == "" | count);
print PolicyType = dynamic(["🛡️ Strict Preset", "🔵 Standard Preset", "⚙️ Custom Policies", "⚠️ No Policy Detected"]),
      Count = pack_array(StrictProtected, StandardProtected, CustomPolicy, NoPolicy),
      Recommendation = dynamic(["✅ Best Protection", "✅ Good Protection", "🔍 Review custom settings", "❌ Apply Preset Policies"])
| mv-expand PolicyType to typeof(string), Count to typeof(long), Recommendation to typeof(string)

// Configuration Compliance Summary
let TotalInbound = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | count);
let DMARCPass = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | extend Auth = parse_json(AuthenticationDetails) | where tostring(Auth.DMARC) == "pass" | count);
let DKIMPass = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | extend Auth = parse_json(AuthenticationDetails) | where tostring(Auth.DKIM) == "pass" | count);
let SPFPass = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailDirection == "Inbound" | extend Auth = parse_json(AuthenticationDetails) | where tostring(Auth.SPF) == "pass" | count);
let ZAPActive = toscalar(EmailPostDeliveryEvents | where TimeGenerated {TimeRange} | where ActionTrigger == "ZAP" | count);
let SafeLinksActive = toscalar(UrlClickEvents | where TimeGenerated {TimeRange} | count);
let ImpersonationBlocks = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where EmailActionPolicy has_any ("impersonation", "Anti-phishing") | count);
let ThreatsBlocked = toscalar(EmailEvents | where TimeGenerated {TimeRange} | where DeliveryAction in ("Blocked", "Quarantined") | where isnotempty(ThreatTypes) | count);
print Check = dynamic(["DMARC Validation", "DKIM Validation", "SPF Validation", "ZAP Active", "Safe Links Active", "Impersonation Protection", "Threat Blocking"]),
      Status = pack_array(
        iff(DMARCPass > TotalInbound * 0.7, "✅ Good", iff(DMARCPass > TotalInbound * 0.5, "🟡 Partial", "❌ Review")),
        iff(DKIMPass > TotalInbound * 0.7, "✅ Good", iff(DKIMPass > TotalInbound * 0.5, "🟡 Partial", "❌ Review")),
        iff(SPFPass > TotalInbound * 0.8, "✅ Good", iff(SPFPass > TotalInbound * 0.6, "🟡 Partial", "❌ Review")),
        iff(ZAPActive > 0, "✅ Active", "❌ No ZAP Activity"),
        iff(SafeLinksActive > 0, "✅ Active", "⚠️ No Data"),
        iff(ImpersonationBlocks > 0, "✅ Active", "⚠️ Review Policy"),
        iff(ThreatsBlocked > 0, "✅ Active", "⚠️ No Blocks")),
      Count = pack_array(DMARCPass, DKIMPass, SPFPass, ZAPActive, SafeLinksActive, ImpersonationBlocks, ThreatsBlocked),
      Percentage = pack_array(
        strcat(tostring(round(toreal(DMARCPass)/TotalInbound*100, 1)), "%"),
        strcat(tostring(round(toreal(DKIMPass)/TotalInbound*100, 1)), "%"),
        strcat(tostring(round(toreal(SPFPass)/TotalInbound*100, 1)), "%"),
        "N/A", "N/A", "N/A", "N/A")
| mv-expand Check to typeof(string), Status to typeof(string), Count to typeof(long), Percentage to typeof(string)

// External Forwarding Detection (V2 - OfficeActivity replaced with CloudAppEvents)
// Inbox-rule / forwarding-related admin actions captured by M365 Defender / Cloud App Events.
// CloudAppEvents contains the Exchange / Set-InboxRule actions previously read from OfficeActivity.
// Identity columns in CloudAppEvents: AccountId (UPN for Office 365 workload),
// AccountDisplayName, AccountObjectId. There is no AccountUpn column.
let ForwardingRules =
    union isfuzzy=true
        (CloudAppEvents
        | where TimeGenerated {TimeRange}
        | where ActionType in~ ("New-InboxRule", "Set-InboxRule", "Set-Mailbox", "UpdateInboxRules")
        | extend Params = tostring(RawEventData)
        | where Params has_any ("ForwardTo", "ForwardAsAttachmentTo", "RedirectTo", "ForwardingSmtpAddress")
        | extend ForwardingTarget = extract(@"(ForwardTo|ForwardAsAttachmentTo|RedirectTo|ForwardingSmtpAddress)[^@]*@([\w.-]+)", 2, Params)
        | where isnotempty(ForwardingTarget)
        | project TimeGenerated, AccountId, AccountDisplayName, ActionType, ForwardingTarget);
ForwardingRules
| summarize
    TotalForwardingRules = count(),
    UniqueUsersWithForwarding = dcount(AccountId),
    ExternalTargets = make_set(ForwardingTarget, 20)
| extend ForwardingStatus = case(
    TotalForwardingRules == 0, "✅ No External Forwarding Detected",
    TotalForwardingRules > 10, "🔴 High Volume - Investigate",
    "🟡 Forwarding Rules Exist - Review")
| project ForwardingStatus, TotalForwardingRules, UniqueUsersWithForwarding, ExternalTargets

// User - Received Threats
let UserFilter = "{InvestigateUser}";
EmailEvents
| where TimeGenerated {TimeRange}
| where isnotempty(UserFilter) and RecipientEmailAddress has UserFilter
| where isnotempty(ThreatTypes)
| project TimeGenerated, SenderFromAddress, SenderDisplayName, Subject, ThreatTypes, DeliveryAction, DeliveryLocation
| order by TimeGenerated desc

// Domain - Email Activity
let DomainFilter = "{InvestigateDomain}";
EmailEvents
| where TimeGenerated {TimeRange}
| where isnotempty(DomainFilter) and SenderFromDomain has DomainFilter
| project TimeGenerated, SenderFromAddress, SenderDisplayName, RecipientEmailAddress, Subject, ThreatTypes, DeliveryAction, AuthenticationDetails
| order by TimeGenerated desc
| take 100

