// Maps to MDO-10 / MDO-11 (ZAP gaps, exposure window) scoped to Teams.
// Joins MessageEvents (initial delivery time) with MessagePostDeliveryEvents
// (remediation time) via TeamsMessageId, then reports median / p90 / max
// exposure minutes grouped by remediation trigger.
let delivery =
    MessageEvents
    | where Timestamp > ago(30d)
    | project TeamsMessageId, DeliveredTime = Timestamp, IsExternalThread;
let action =
    MessagePostDeliveryEvents
    | where Timestamp > ago(30d)
    | project TeamsMessageId, ActionTime = Timestamp, Action, ActionTrigger, ActionResult;
delivery
| join kind=inner action on TeamsMessageId
| extend ExposureMinutes = datetime_diff('minute', ActionTime, DeliveredTime)
| where ExposureMinutes >= 0
| summarize
    Actions          = count(),
    ExternalActions  = countif(IsExternalThread == true),
    SuccessfulActions= countif(ActionResult =~ "Success"),
    MedianExposureMin= percentile(ExposureMinutes, 50),
    P90ExposureMin   = percentile(ExposureMinutes, 90),
    MaxExposureMin   = max(ExposureMinutes)
    by ActionTrigger
| top 10 by Actions desc
