//  * Single-column `top 25 by Detections desc`.
union isfuzzy=true
    (FileMaliciousContentInfo
    | where Timestamp > ago(30d)
    | where isnotempty(FileOwnerUpn))
| summarize
    Detections  = count(),
    UniqueFiles = dcount(SHA256),
    Workloads   = make_set(Workload, 5),
    Threats     = make_set(tostring(ThreatTypes), 5),
    OwnerName   = any(FileOwnerDisplayName),
    FirstSeen   = min(Timestamp),
    LastSeen    = max(Timestamp)
    by FileOwnerUpn
| top 25 by Detections desc
